Definition SsvcCells (S : svch) (implb : Z) (j7 : list byte) : list cell :=
  SvcHdrCells S ++ [C8 (wz (implb + O_SPC_STORAGE)); C8 (wz implb)] ++ CookieCells j7.

Section HCW.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis ATR : incl TRLIST (as_TR H).

  (* [comment removed for export] *)
  Lemma ah_lb_remove_nodup : forall p LB, List.NoDup (map blk_id LB) -> List.NoDup (map blk_id (as_lb_remove H p LB)).
  Proof.
    intros p LB. induction LB as [|c LB IH]; intros ND.
    - assert (E : as_lb_remove H p [] = []).
      { destruct (as_lb_remove H p []) as [|b l] eqn:K; [reflexivity|]. exfalso. pose proof (ah_lb_remove_In H HH p [] b) as IN. rewrite K in IN. exact (IN (or_introl eq_refl)). }
      rewrite E. constructor.
    - cbn in ND. inversion ND as [|x l NI ND']; subst.
      destruct (bptr_eq_dec (blk_id c) p) as [E|NE].
      + destruct c as [[pc Ac] nc]. cbn in E. subst pc. rewrite (proj1 (ah_lb_remove H HH)) by exact NI. exact ND'.
      + rewrite (ah_lb_remove_cons_ne H HH) by exact NE. cbn. constructor; [| exact (IH ND')].
        intros K. apply NI. apply in_map_iff in K. destruct K as (b & Eb & INb). rewrite <- Eb. apply in_map. exact (ah_lb_remove_In H HH _ _ _ INb).
  Qed.

