    (F : bvmap 5 word) (fc : bv 32) (m : mem) (v implb lo shi : Z) (S : svch) (j7 : list byte),
  rw_cells bsegs m v (SsvcCells S implb j7) -> sv_vptr S = AVP_SSVC ->
  aapp v NEWSZ_SSVC -> v mod 16 = 0 -> addressable m v NEWSZ_SSVC ->
  stk bsegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m -> ACONST m -> stack0 m lo shi ->
  evt bsegs (ssd_segA_post ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc v implb lo shi S j7 m)
